import{_ as i,C as o,o as n,c as s,j as d,a as e,E as a,ag as l}from"./chunks/framework.HG0H2VLS.js";const S=JSON.parse('{"title":"StatCard","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/stat-card.md","filePath":"patterns/stat-card.md"}'),p={name:"patterns/stat-card.md"},g={id:"statcard",tabindex:"-1"};function h(u,t,m,f,v,b){const r=o("Badge"),c=o("ComponentDemo");return n(),s("div",null,[t[3]||(t[3]=d("hr",null,null,-1)),t[4]||(t[4]=d("h2",{id:"title-statcard",tabindex:"-1"},[e("title: StatCard "),d("a",{class:"header-anchor",href:"#title-statcard","aria-label":'Permalink to "title: StatCard"'},"​")],-1)),d("h1",g,[t[0]||(t[0]=e("StatCard ",-1)),a(r,{type:"info",text:"Design System"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#statcard","aria-label":'Permalink to "StatCard <Badge type="info" text="Design System" />"'},"​",-1))]),t[5]||(t[5]=d("blockquote",null,[d("p",null,"47 Figma variants: Size (Base/Lg) × Type (Default / Chevron Down / Chevron Right / No card / Number First) in Blue, plus all 38 Fill values (19 accents × solid/soft) on Base/Default")],-1)),a(c,{src:"/demos/src/patterns/StatCard/StatCard.html"}),t[6]||(t[6]=l('<h2 id="variant-matrix" tabindex="-1">Variant matrix <a class="header-anchor" href="#variant-matrix" aria-label="Permalink to &quot;Variant matrix&quot;">​</a></h2><p>52 Figma variants: 3 Sizes (Sm added 2026-09-28) × 5 Types with <code>Fill=Blue</code>, plus all 38 Fill values (19 accents × solid/soft) on <strong>Base / Default</strong>. Other Size × Type combos exist in Blue only in Figma; code supports every Fill on every Size × Type.</p><table tabindex="0"><thead><tr><th>Node</th><th>Size</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>2758:3019</code></td><td>Base</td><td>Default</td><td>h-64, icon-wrap 40, icon 16</td></tr><tr><td><code>2758:3029</code></td><td>Base</td><td>Chevron Down</td><td>+ chevron-down 16 on right</td></tr><tr><td><code>2758:3039</code></td><td>Base</td><td>Chevron Right</td><td>+ chevron-right 16 on right</td></tr><tr><td><code>2758:3049</code></td><td>Base</td><td>No card</td><td>no border/shadow/padding, h-40</td></tr><tr><td><code>2758:3057</code></td><td>Base</td><td>Number First</td><td>value above title</td></tr><tr><td><code>3900:1754</code></td><td>Sm</td><td>Default</td><td>h-56 (min spacing-10), gap + padding spacing-3, title 2xs (13px)</td></tr><tr><td><code>3900:1762</code></td><td>Sm</td><td>Chevron Down</td><td>Sm + chevron</td></tr><tr><td><code>3900:1772</code></td><td>Sm</td><td>Chevron Right</td><td>Sm + chevron</td></tr><tr><td><code>3900:1782</code></td><td>Sm</td><td>No card</td><td>Sm + no card (h-40, padding 0)</td></tr><tr><td><code>3900:1790</code></td><td>Sm</td><td>Number First</td><td>Sm + swapped order</td></tr><tr><td><code>2758:3076</code></td><td>Lg</td><td>Default</td><td>h-80, icon-wrap 48, icon 20</td></tr><tr><td><code>2758:3082</code></td><td>Lg</td><td>Chevron Down</td><td>Lg + chevron</td></tr><tr><td><code>2758:3089</code></td><td>Lg</td><td>Chevron Right</td><td>Lg + chevron</td></tr><tr><td><code>2758:3096</code></td><td>Lg</td><td>No card</td><td>Lg + no card (h-48)</td></tr><tr><td><code>2758:3102</code></td><td>Lg</td><td>Number First</td><td>Lg + swapped order</td></tr><tr><td><code>3821:130490…</code> + <code>3850:185…465</code></td><td>Base</td><td>Default, Fill=<code>&lt;Colour&gt;</code> / <code>&lt;Colour&gt; Soft</code></td><td>37 variants — Fill value = colour name (e.g. <code>Teal Radix Soft</code>) → <code>stat-card--teal-radix stat-card--soft</code></td></tr></tbody></table><p>All 10 <code>Fill=Blue</code> variants = <code>stat-card--blue</code> (the default — no modifier needed).</p><h3 id="fill-axis-code" tabindex="-1">Fill axis (code) <a class="header-anchor" href="#fill-axis-code" aria-label="Permalink to &quot;Fill axis (code)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Modifier</th><th>Square</th><th>Icon</th></tr></thead><tbody><tr><td><code>stat-card--&lt;colour&gt;</code></td><td><code>--ai-accent-&lt;colour&gt;-solid</code></td><td><code>--ai-accent-&lt;colour&gt;-solid-fg</code></td></tr><tr><td><code>+ stat-card--soft</code></td><td><code>--ai-accent-&lt;colour&gt;-soft</code></td><td><code>--ai-accent-&lt;colour&gt;-soft-fg</code></td></tr></tbody></table><p>Colours (19): <code>blue</code> (default), <code>mid-blue</code>, <code>dark-blue</code>, <code>emerald</code>, <code>orange</code>, <code>pink</code>, <code>red</code>, <code>green</code>, <code>purple</code>, <code>indigo</code>, <code>blue-radix</code>, <code>teal-radix</code>, <code>green-radix</code>, <code>jade</code>, <code>lagoon</code>, <code>orange-radix</code>, <code>red-radix</code>, <code>violet-radix</code>, <code>lime-radix</code>.</p><p>Each colour modifier only re-points four component props (<code>--stat-card-solid</code>, <code>-solid-fg</code>, <code>-soft</code>, <code>-soft-fg</code>); <code>.stat-card__icon-wrap</code> reads solid, <code>.stat-card--soft</code> switches it to soft.</p><hr><h2 id="css-class-mapping" tabindex="-1">CSS class mapping <a class="header-anchor" href="#css-class-mapping" aria-label="Permalink to &quot;CSS class mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>Root frame</td><td><code>.stat-card</code> (<code>&lt;div&gt;</code>)</td></tr><tr><td>Sm size</td><td><code>.stat-card--sm</code></td></tr><tr><td>Lg size</td><td><code>.stat-card--lg</code></td></tr><tr><td>Type=No card</td><td><code>.stat-card--no-card</code></td></tr><tr><td>Type=Number First</td><td><code>.stat-card--number-first</code> (uses <code>order</code> to swap)</td></tr><tr><td><code>Fill=&lt;colour&gt;</code></td><td><code>.stat-card--&lt;colour&gt;</code></td></tr><tr><td><code>Fill=&lt;colour&gt; Soft</code></td><td><code>.stat-card--&lt;colour&gt;.stat-card--soft</code></td></tr><tr><td>Brand icon square</td><td><code>.stat-card__icon-wrap</code></td></tr><tr><td>Lucide icon (inside square)</td><td><code>&lt;i data-lucide=&quot;...&quot; aria-hidden=&quot;true&quot;&gt;</code></td></tr><tr><td>Text column</td><td><code>.stat-card__text</code></td></tr><tr><td>Title (label)</td><td><code>.stat-card__title</code> (<code>&lt;p&gt;</code>)</td></tr><tr><td>Number (value)</td><td><code>.stat-card__value</code> (<code>&lt;p&gt;</code>)</td></tr><tr><td>Chevron icon (right)</td><td><code>.stat-card__chevron</code> + Lucide</td></tr></tbody></table><p>For Chevron Down/Right variants, add <code>&lt;div class=&quot;stat-card__chevron&quot;&gt;</code> as a sibling after <code>.stat-card__text</code>.</p><hr><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Token</th><th>Notes</th></tr></thead><tbody><tr><td>Card bg</td><td><code>var(--ai-surface-primary)</code></td><td>white (transparent on <code>--no-card</code>)</td></tr><tr><td>Card border</td><td><code>1px solid var(--ai-border-secondary)</code></td><td>(none on <code>--no-card</code>)</td></tr><tr><td>Card shadow</td><td><code>var(--ai-shadow-md)</code></td><td>maps to Figma <code>light/shadow-md</code>; removed on <code>--no-card</code></td></tr><tr><td>Card radius</td><td><code>var(--ai-radius-md)</code></td><td>8px (Figma bound <code>--ai-spacing-3</code> — designer-approved swap)</td></tr><tr><td>Card gap (Base)</td><td><code>var(--ai-spacing-4)</code></td><td>12px</td></tr><tr><td>Card gap / padding (Sm)</td><td><code>var(--ai-spacing-3)</code></td><td>8px</td></tr><tr><td>Card min-height (Sm + card)</td><td><code>var(--ai-spacing-10)</code></td><td>56px</td></tr><tr><td>Title font-size (Sm)</td><td><code>var(--ai-font-fixed-2xs)</code></td><td>13px</td></tr><tr><td>Card gap (Lg)</td><td><code>var(--ai-spacing-5)</code></td><td>16px</td></tr><tr><td>Card padding (Base)</td><td><code>var(--ai-spacing-4)</code></td><td>12px</td></tr><tr><td>Card padding (Lg)</td><td><code>var(--ai-spacing-5)</code></td><td>16px</td></tr><tr><td>Card min-height (Base + card)</td><td><code>var(--ai-spacing-11)</code></td><td>64px</td></tr><tr><td>Card min-height (Lg + card)</td><td><code>var(--ai-spacing-13)</code></td><td>80px</td></tr><tr><td>Card min-height (Base + no-card)</td><td><code>var(--ai-spacing-8)</code></td><td>40px</td></tr><tr><td>Card min-height (Lg + no-card)</td><td><code>var(--ai-spacing-9)</code></td><td>48px</td></tr><tr><td>Icon-wrap bg (solid)</td><td><code>var(--ai-accent-&lt;colour&gt;-solid)</code></td><td>via <code>--stat-card-solid</code>; default <code>--ai-accent-blue-solid</code></td></tr><tr><td>Icon colour (solid)</td><td><code>var(--ai-accent-&lt;colour&gt;-solid-fg)</code></td><td>white, or Grey/850 on light squares</td></tr><tr><td>Icon-wrap bg (soft)</td><td><code>var(--ai-accent-&lt;colour&gt;-soft)</code></td><td>via <code>--stat-card-soft</code></td></tr><tr><td>Icon colour (soft)</td><td><code>var(--ai-accent-&lt;colour&gt;-soft-fg)</code></td><td></td></tr><tr><td>Icon-wrap size (Base)</td><td><code>var(--ai-spacing-8)</code></td><td>40px</td></tr><tr><td>Icon-wrap size (Lg)</td><td><code>var(--ai-spacing-9)</code></td><td>48px</td></tr><tr><td>Icon-wrap radius</td><td><code>var(--ai-radius-md)</code></td><td>8px</td></tr><tr><td>Inner icon size (Base)</td><td><code>var(--ai-icon-size-sm)</code></td><td>16px</td></tr><tr><td>Inner icon size (Lg)</td><td><code>var(--ai-icon-size-md)</code></td><td>20px</td></tr><tr><td>Chevron icon size</td><td><code>var(--ai-icon-size-sm)</code></td><td>16px (same in Base + Lg)</td></tr><tr><td>Chevron colour</td><td><code>var(--ai-icon-secondary)</code></td><td></td></tr><tr><td>Text column gap</td><td><code>var(--ai-spacing-1)</code></td><td>4px</td></tr><tr><td>Title font</td><td><code>var(--ai-font-body)</code> + <code>var(--ai-font-medium)</code></td><td>Inter Medium</td></tr><tr><td>Title size</td><td><code>var(--ai-font-fixed-xs)</code></td><td>14px</td></tr><tr><td>Title colour</td><td><code>var(--ai-text-contrast)</code></td><td></td></tr><tr><td>Value font</td><td><code>var(--ai-font-title)</code> + <code>var(--ai-font-bold)</code></td><td>Inter Bold</td></tr><tr><td>Value size</td><td><code>var(--ai-font-fixed-sm)</code></td><td>16px</td></tr><tr><td>Value colour</td><td><code>var(--ai-text-primary)</code></td><td></td></tr></tbody></table><hr><h2 id="token-gaps" tabindex="-1">Token gaps <a class="header-anchor" href="#token-gaps" aria-label="Permalink to &quot;Token gaps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Property</th><th>Figma</th><th>Resolution</th></tr></thead><tbody><tr><td>1</td><td>Icon-wrap bg</td><td><s><code>Blue/600</code> primitive <code>#2563eb</code></s></td><td><strong>RESOLVED 2026-09-28</strong> — <code>accent/*</code> semantic set added to Figma (84 vars); Figma variants rebound; CSS uses <code>--ai-accent-*</code>.</td></tr><tr><td>2</td><td>Card radius binding</td><td>Figma binds <code>--ai-spacing-3</code> (8px)</td><td>User-approved: use <code>--ai-radius-md</code> instead (same value, correct semantic).</td></tr><tr><td>3</td><td>Card width</td><td>Figma frame width 339px (no token)</td><td>User-approved: width is consumer-controlled — <code>width: 100%</code>.</td></tr><tr><td>4</td><td>No card bg</td><td>Figma keeps <code>--ai-surface-primary</code> (white)</td><td>User-approved: render as <code>background: transparent</code> so the &quot;no card&quot; variant has no chrome whatsoever (literally just icon + text on the parent bg).</td></tr></tbody></table><hr><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-09-28: Fill axis — 21 accent colours × solid/soft via new <code>--ai-accent-*</code> tokens; all 42 fills added to Figma on Base/Default (51 variants); icon-wrap primitive gap resolved; Figma variants rebound to <code>accent/*</code>.</li><li>2026-05-28: Initial build from Figma frame <code>2758:3020</code>. All 10 variants implemented. 4 STOPs resolved (icon-wrap bg primitive, radius rebind, consumer-controlled width, transparent no-card bg).</li></ul><h2 id="sm-size-designer-2026-09-28" tabindex="-1">Sm size (designer, 2026-09-28) <a class="header-anchor" href="#sm-size-designer-2026-09-28" aria-label="Permalink to &quot;Sm size (designer, 2026-09-28)&quot;">​</a></h2><p>From the designer&#39;s live amends on Article Edit: gap + padding <code>--ai-spacing-3</code>, min-height <code>--ai-spacing-10</code>, title <code>--ai-font-fixed-2xs</code>. Icon block (32 / 16px icon), value and radius unchanged from Base. Built in Figma as 5 Blue variants like Lg; first consumer = the record screens&#39; PerformanceSummary.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Width is intentionally <strong>100% of parent</strong> — Figma frame uses 339px but the production component is layout-agnostic.</li><li><strong>Number First</strong> swaps title and value order via CSS <code>order</code> (no HTML restructuring needed) — markup stays consistent across all variants.</li><li><strong>No card</strong> transparent background diverges from Figma (which keeps the white surface-primary) so the variant works on any parent surface. User-approved.</li><li>Chevron variants are <strong>static decorations</strong> — no JS, no expand/collapse, no click handler. Consumer wraps the card in <code>&lt;a&gt;</code> or <code>&lt;button&gt;</code> if interaction is needed.</li><li><strong>Accent tokens</strong> (<code>accent/&lt;colour&gt;/{solid,solid-fg,soft,soft-fg}</code>, Semantic collection) alias primitives: Radix ramps use steps 9 / 3 / 11 (dark soft 12 / 9); the 100–900 ramps use 600 / 100 / 700 (dark soft 900 / 400). Contrast-driven exceptions: dark (Grey/850) icon on solid Orange Radix, Lime Radix, Bright Teal, Green; soft icon 800 on Bright Teal, Green; dark soft square 13 on Orange Radix; dark soft icon 8 on Violet Radix. All 42 fills ≥ 3:1 in all 6 modes (verified headless).</li><li>Solid squares keep the light value in dark mode; soft squares move to a dark step.</li><li>The Figma soft variants originally bound the external &quot;Radix Full&quot; collection (<code>purple</code>, <code>crimson</code>, <code>grass</code> have no ramp of ours) — rebound to <code>purple</code> / <code>pink</code> / <code>green-radix</code>, and every soft icon moved from step 9 (2.6–2.9:1, failing) to step 11. Fill values renamed to match the code slugs: Blue Soft → Blue Radix Soft, Aqua Soft → Teal Radix Soft, Green Soft → Green Radix Soft.</li><li>Soft squares on the palest ramps moved up for legibility on a white card: <code>mid-blue</code>, <code>dark-blue</code> → 200; <code>green</code> → 300.</li><li><strong>Muted Teal and Bright Teal removed</strong> (2026-09-28) from StatCard in Figma and code — use <code>lagoon</code> / <code>teal-radix</code>. Their <code>--ai-accent-*</code> tokens still exist (Lagoon-sourced) but nothing uses them.</li><li>Solid Blue changed colour: stale <code>#2563eb</code> → current <code>Blue/600</code> <code>#0071d8</code>.</li></ul><hr><h2 id="figma" tabindex="-1">Figma <a class="header-anchor" href="#figma" aria-label="Permalink to &quot;Figma&quot;">​</a></h2><p><a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino-AI---Design-System?node-id=2758-3020" target="_blank" rel="noreferrer">Open in Figma</a></p>',28))])}const C=i(p,[["render",h]]);export{S as __pageData,C as default};
